import sys

def summary_ranges_brute(nums):
    n = len(nums)
    res = []
    start = 0
    for i in range(n):
        if i == n - 1 or nums[i + 1] != nums[i] + 1:
            if start == i:
                res.append(str(nums[i]))
            else:
                res.append(f'{nums[start]}->{nums[i]}')
            start = i + 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for r in summary_ranges_brute(nums):
        print(r)

import sys

def summary_ranges_opt(nums):
    res = []
    i, n = 0, len(nums)
    while i < n:
        start = i
        while i + 1 < n and nums[i + 1] == nums[i] + 1:
            i += 1
        if start == i:
            res.append(str(nums[i]))
        else:
            res.append(f'{nums[start]}->{nums[i]}')
        i += 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    for r in summary_ranges_opt(nums):
        print(r)
